@router.get("/api/v1/tags/{tag_id}/documents", response_model=List[DocumentRead])
def get_documents_by_tag(
    tag_id: uuid.UUID,
    session: Session = Depends(get_session),
    current_user: User = Depends(get_current_user)
):
    tag = session.get(Tag, tag_id)
    if not tag:
        raise HTTPException(status_code=404, detail="Tag not found")
    stmt = (
        select(Document)
        .join(DocumentTagLink)
        .where(DocumentTagLink.tag_id == tag_id, Document.tenant_id == current_user.tenant_id)
    )
    return session.exec(stmt).all()
